"""Commands generated by the policy run only in disposable containers."""
from __future__ import annotations
import hashlib
import os
import re
import shlex
import subprocess
import uuid
from pathlib import Path
from .core import StudyError


def docker(executable, args, timeout=120):
    try:
        p = subprocess.run([executable, *args], capture_output=True, timeout=timeout)
    except (OSError, subprocess.TimeoutExpired):
        raise StudyError("Docker command failed or timed out") from None
    if p.returncode:
        raise StudyError("Docker operation failed: " + p.stderr.decode("utf-8", "replace")[-1500:])
    return p.stdout.decode("utf-8", "replace")


def inspect_image(executable, image):
    import json
    return json.loads(docker(executable, ["image", "inspect", image]))[0]


class DockerSession:
    def __init__(self, image_id, base_commit, settings, ttl=3800):
        if not re.fullmatch(r"[0-9a-f]{40}", base_commit):
            raise StudyError("Invalid task base commit")
        self.exe = settings.get("executable", "docker")
        self.base = base_commit
        self.container = None
        self.settings = settings
        self.container = docker(self.exe, ["run", "-d", "--rm", "--network", "none", "--memory", settings.get("memory", "8g"), "--cpus", str(settings.get("cpus", 4)), "--pids-limit", str(settings.get("pids_limit", 1024)), "--label", "experiment=d3-bon-study", "--name", "d3study-" + uuid.uuid4().hex[:12], "--workdir", "/testbed", image_id, "sleep", str(ttl)], timeout=120).strip()
        try:
            r = self.execute("git reset --hard " + shlex.quote(base_commit), 60, trusted=True)
            s = self.execute("git rev-parse HEAD", 30, trusted=True)
            if r["returncode"] or s["output"].strip() != base_commit:
                raise StudyError("Fresh container could not checkout the pinned task base")
        except BaseException:
            try:
                self.close()
            except Exception:
                pass
            raise

    def execute(self, command, timeout, *, trusted=False):
        if not self.container:
            raise StudyError("Container is not running")
        limit = max(1, int(timeout))
        shell = "/bin/bash --noprofile --norc" if trusted else "bash"
        wrapped = "/usr/bin/timeout --signal=TERM --kill-after=5s " + str(limit) + "s " + shell + " -c " + shlex.quote(command)
        environment = ["-e", "BASH_ENV=", "-e", "PATH=/usr/bin:/bin"] if trusted else ["-e", "BASH_ENV=/root/.bashrc"]
        try:
            p = subprocess.run([self.exe, "exec", "--workdir", "/testbed", *environment, "-e", "PAGER=cat", self.container, "/bin/bash", "--noprofile", "--norc", "-c", wrapped], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=limit + 10)
            return {"returncode": p.returncode, "output": p.stdout.decode("utf-8", "replace")}
        except subprocess.TimeoutExpired as error:
            return {"returncode": 124, "output": (error.stdout or b"").decode("utf-8", "replace"), "controller_timeout": True}
        except OSError:
            raise StudyError("Docker execution unavailable") from None

    def extract(self):
        # These operations affect only our disposable container, never the host.
        add = self.execute("git ls-files --others --exclude-standard -z | xargs -0 -r git add -N --", 30, trusted=True)
        diff = self.execute("git -c core.quotePath=false diff --no-ext-diff --binary " + self.base + " -- .", 30, trusted=True)
        names = self.execute("git diff --no-ext-diff --name-only -z " + self.base + " -- .", 30, trusted=True)
        if add["returncode"] or diff["returncode"] or names["returncode"]:
            raise StudyError("Final patch extraction failed")
        return diff["output"], [s for s in names["output"].split("\0") if s]

    def close(self):
        if not self.container:
            return
        name = self.container
        last = "unknown"
        for _ in range(3):
            try:
                process = subprocess.run([self.exe, "rm", "-f", name], capture_output=True, timeout=60)
            except (OSError, subprocess.TimeoutExpired) as error:
                last = str(error)
                continue
            text = (process.stderr or b"").decode("utf-8", "replace")
            if process.returncode == 0 or "no such" in text.lower() or "not found" in text.lower():
                self.container = None
                return
            last = text[-500:]
        self.container = None
        raise StudyError("Container cleanup failed: " + last[:500])


def file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def enroot_uri(tag):
    if tag.startswith("docker.io/"):
        return "docker://docker.io#" + tag[len("docker.io/"):]
    return "docker://" + tag


def _enroot_env(settings):
    runtime = settings.get("enroot_runtime") or f"/tmp/enroot-{os.getuid()}"
    Path(runtime).mkdir(parents=True, exist_ok=True)
    env = os.environ.copy()
    # Host CUDA compatibility libraries must not leak into the task rootfs.
    env.pop("LD_LIBRARY_PATH", None)
    env.update({
        "ENROOT_DATA_PATH": settings["enroot_data"],
        "ENROOT_CACHE_PATH": settings["enroot_cache"],
        "ENROOT_RUNTIME_PATH": runtime,
        "ENROOT_TEMP_PATH": settings.get("enroot_temp") or env.get("TMPDIR") or "/tmp",
    })
    return env


def enroot_import(settings, tag, output):
    env = _enroot_env(settings)
    Path(settings["enroot_data"]).mkdir(parents=True, exist_ok=True)
    Path(settings["enroot_cache"]).mkdir(parents=True, exist_ok=True)
    Path(output).parent.mkdir(parents=True, exist_ok=True)
    try:
        process = subprocess.run(["enroot", "import", "-o", str(output), enroot_uri(tag)], env=env, timeout=settings.get("image_pull_timeout_seconds", 3600), capture_output=True, text=True)
    except (OSError, subprocess.TimeoutExpired):
        raise StudyError(f"Enroot could not import {tag}") from None
    if process.returncode:
        raise StudyError(f"Enroot could not import {tag}: {(process.stderr or process.stdout)[-1500:]}")
    return {"tag": tag, "id": file_sha256(output), "sqsh": str(output)}


class EnrootSession:
    """Persistent writable Enroot sandbox. Each command is a fresh start; rootfs changes outside /tmp persist."""

    def __init__(self, image_path, base_commit, settings, ttl=3800):
        if not re.fullmatch(r"[0-9a-f]{40}", base_commit):
            raise StudyError("Invalid task base commit")
        if not image_path or not Path(image_path).is_file():
            raise StudyError("Enroot image file is missing")
        self.base = base_commit
        self.settings = settings
        self.env = _enroot_env(settings)
        self.name = "d3" + uuid.uuid4().hex[:12]
        self.ttl = ttl
        try:
            subprocess.run(["enroot", "create", "--name", self.name, image_path], check=True, env=self.env, timeout=1800)
            created = self.execute("git rev-parse HEAD", 60, trusted=True)
            reset = self.execute("git reset --hard " + shlex.quote(base_commit), 60, trusted=True)
            head = self.execute("git rev-parse HEAD", 30, trusted=True)
            if created["returncode"] or reset["returncode"] or head["output"].strip() != base_commit:
                raise StudyError("Fresh container could not checkout the pinned task base")
        except BaseException:
            try:
                self.close()
            except Exception:
                pass
            raise

    def execute(self, command, timeout, *, trusted=False, mounts=()):
        limit = max(1, int(timeout))
        shell = "/bin/bash --noprofile --norc" if trusted else "bash"
        wrapped = "cd /testbed && /usr/bin/timeout --signal=TERM --kill-after=5s " + str(limit) + "s " + shell + " -c " + shlex.quote(command)
        command_line = ["enroot", "start", "-w", "-r"]
        for mount in mounts:
            command_line.extend(["-m", mount])
        command_line.extend([self.name, "bash", "--noprofile", "--norc", "-c", wrapped])
        try:
            process = subprocess.run(
                command_line,
                env=self.env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=limit + 30,
            )
            return {"returncode": process.returncode, "output": process.stdout.decode("utf-8", "replace")}
        except subprocess.TimeoutExpired as error:
            return {"returncode": 124, "output": (error.stdout or b"").decode("utf-8", "replace"), "controller_timeout": True}
        except OSError:
            raise StudyError("Enroot execution unavailable") from None

    def extract(self):
        add = self.execute("git ls-files --others --exclude-standard -z | xargs -0 -r git add -N --", 30, trusted=True)
        diff = self.execute("git -c core.quotePath=false diff --no-ext-diff --binary " + self.base + " -- .", 30, trusted=True)
        names = self.execute("git diff --no-ext-diff --name-only -z " + self.base + " -- .", 30, trusted=True)
        if add["returncode"] or diff["returncode"] or names["returncode"]:
            raise StudyError("Final patch extraction failed")
        return diff["output"], [item for item in names["output"].split("\0") if item]

    def close(self):
        last = "unknown"
        for _ in range(3):
            try:
                process = subprocess.run(["enroot", "remove", "-f", self.name], env=self.env, capture_output=True, timeout=120)
            except (OSError, subprocess.TimeoutExpired) as error:
                last = str(error)
                continue
            text = (process.stderr or process.stdout or b"").decode("utf-8", "replace")
            lowered = text.lower()
            if process.returncode == 0 or "no such" in lowered or "not found" in lowered or "does not exist" in lowered:
                return
            last = text[-500:]
        raise StudyError("Enroot cleanup failed: " + last[:500])
